INSERT INTO `crs_tabledata687` VALUES ('2974', '{6241C22B-3BAE-463C-BA62-ECAA3A87A045}', '0', 'INHE-0287', '2013-07-18 14:45:56', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '1', 'MY', null, null, ' ', ' ', ' ', '需求演示箱里的产品即为我们现有预付费代码表（附件无特殊技术规格要求）；\r\n演示箱需包括：“1P 100A 和3P 100A的直通式预付费代码表各一(多费率)+集中器+集抄售电软件（演示版）”  (即在现有演示箱基础上换个3P相表进去即可)\r\n\r\n实现通讯:PLC+GPRS/Ethernet； RS485', ' ', '');
INSERT INTO `crs_tabledata687` VALUES ('2975', '{6241C22B-3BAE-463C-BA62-ECAA3A87A046}', '0', 'INHE-0287', '2013-07-10 15:48:12', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '1', 'GD', null, null, '单相RF卡预付费电表', '', '', '1. 与我司之前出过货的GN01项目产品相同。每个美食广场30个商铺/电表，这30个电表会集中安装在靠近管理中心的位置（距离都在100m以内），通过RS485接出总线，到管理中心，再通过转换器，连接到PC，实现集抄通讯。\r\n2. 当地上百个美食广场是相互独立的，每个美食广场有自己独立的管理中心。\r\n3. 客户只是需要集抄去实现自动抄表以及用户用电数据的获取，对于售电，客户需要的是用户自己去管理中心对卡进行充值，然后回到自己电表处人工进行充值。\r\n（已经与技术支持以及技术部确认，目前现成产品完全满足）', '3000', '');
