INSERT INTO `crs_tabledata687` VALUES ('2991', '{6241C22B-3BAE-463C-BA62-ECAA3A87A062}', '0', 'JXINHE-2559', '2015-09-23 18:24:00', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '1', 'NS', null, null, '带部分防窃电功能的单相电表', '', '', '带部分防窃电和事件记录功能的普通单相表\r\n1.基本参数:额定电流5(30)A 额定电压230V 脉冲常数≤3200imp/kWh\r\n2.防窃电\r\n(1)相线和零线反接(反向指示灯显示)\r\n(2)进线和出线倒装\r\n(3)反接与进出线倒装的组合\r\n(4)全部负载接地同时相线与零线反接\r\n(5)部分负载接地\r\n(6)断零线\r\n(7)磁场干扰\r\n3.事件记录----至少记录25个事件并附有日期与时间\r\n4.背光\r\n5.后备电池\r\n6.延伸加大型透明端子盖', '4000', '');
INSERT INTO `crs_tabledata687` VALUES ('2992', '{6241C22B-3BAE-463C-BA62-ECAA3A87A063}', '0', 'JXINHE-2433', '2015-08-31 10:04:59', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '1', 'YD', null, null, '三相四线CT表0.5s级', '', '', '1.主要技术规格：\r\n（1）额定电压：3*415V\r\n（2）标定电流：3*5（6）A（在1A或5A之间可编程）\r\n（3）频率：50HZ\r\n2. 主要功能\r\n（1）计量总的正向有功电能和反向有功电能及每相的正向和反向有功电能。\r\n（2）多费率\r\n（3）负荷曲线---至少365天\r\n（4）计量最大需量\r\n（5）事件记录---防窃电等50个事件记录\r\n（6）防窃电----防CT短接，反接，逆相序，掉相线，掉零线，外部磁场干扰，高压警棍电击等\r\n（7）通讯接口---RS485接口，近红外探头通讯和掌上电脑抄读，此', '600台', '');
INSERT INTO `crs_tabledata687` VALUES ('2993', '{6241C22B-3BAE-463C-BA62-ECAA3A87A064}', '0', 'JXINHE-2433', '2015-08-31 10:04:59', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '1', 'YD', null, null, '\r\n三相四线GPRS通讯模块CT表0.5s级', '', '', '1.主要技术规格：\r\n（1）额定电压：3*415V\r\n（2）标定电流：3*5（6）A（在1A或5A之间可编程）\r\n（3）频率：50HZ\r\n2. 主要功能\r\n（1）计量总的正向有功电能和反向有功电能及每相的正向和反向有功电能。\r\n（2）多费率\r\n（3）负荷曲线---至少365天\r\n（4）计量最大需量\r\n（5）事件记录---防窃电等50个事件记录\r\n（6）防窃电----防CT短接，反接，逆相序，掉相线，掉零线，外部磁场干扰，高压警棍电击等\r\n（7）通讯接口---RS485接口，近红外探头通讯和掌上电脑抄读，此', '600台', '');
INSERT INTO `crs_tabledata687` VALUES ('2994', '{6241C22B-3BAE-463C-BA62-ECAA3A87A065}', '0', 'JXINHE-2433', '2015-08-31 10:04:59', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '1', 'YD', null, null, '\r\n外置GPRS采集器', '', '', '1.主要技术规格：\r\n（1）额定电压：3*415V\r\n（2）标定电流：3*5（6）A（在1A或5A之间可编程）\r\n（3）频率：50HZ\r\n2. 主要功能\r\n（1）计量总的正向有功电能和反向有功电能及每相的正向和反向有功电能。\r\n（2）多费率\r\n（3）负荷曲线---至少365天\r\n（4）计量最大需量\r\n（5）事件记录---防窃电等50个事件记录\r\n（6）防窃电----防CT短接，反接，逆相序，掉相线，掉零线，外部磁场干扰，高压警棍电击等\r\n（7）通讯接口---RS485接口，近红外探头通讯和掌上电脑抄读，此', '600台', '');
INSERT INTO `crs_tabledata687` VALUES ('2995', '{6241C22B-3BAE-463C-BA62-ECAA3A87A066}', '0', 'JXINHE-2433', '2015-08-31 10:04:59', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '1', 'YD', null, null, '\r\nSmartview软件', '', '', '1.主要技术规格：\r\n（1）额定电压：3*415V\r\n（2）标定电流：3*5（6）A（在1A或5A之间可编程）\r\n（3）频率：50HZ\r\n2. 主要功能\r\n（1）计量总的正向有功电能和反向有功电能及每相的正向和反向有功电能。\r\n（2）多费率\r\n（3）负荷曲线---至少365天\r\n（4）计量最大需量\r\n（5）事件记录---防窃电等50个事件记录\r\n（6）防窃电----防CT短接，反接，逆相序，掉相线，掉零线，外部磁场干扰，高压警棍电击等\r\n（7）通讯接口---RS485接口，近红外探头通讯和掌上电脑抄读，此', '1件', '');
INSERT INTO `crs_tabledata687` VALUES ('2996', '{6241C22B-3BAE-463C-BA62-ECAA3A87A067}', '0', 'JXINHE-2433', '2015-08-31 10:04:59', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '1', 'YD', null, null, '\r\n红外探头/USB接口的掌上电脑（可以买到）', '', '', '1.主要技术规格：\r\n（1）额定电压：3*415V\r\n（2）标定电流：3*5（6）A（在1A或5A之间可编程）\r\n（3）频率：50HZ\r\n2. 主要功能\r\n（1）计量总的正向有功电能和反向有功电能及每相的正向和反向有功电能。\r\n（2）多费率\r\n（3）负荷曲线---至少365天\r\n（4）计量最大需量\r\n（5）事件记录---防窃电等50个事件记录\r\n（6）防窃电----防CT短接，反接，逆相序，掉相线，掉零线，外部磁场干扰，高压警棍电击等\r\n（7）通讯接口---RS485接口，近红外探头通讯和掌上电脑抄读，此', '100个', '');
