INSERT INTO `crs_tabledata687` VALUES ('2998', '{6241C22B-3BAE-463C-BA62-ECAA3A87A069}', '0', 'JXINHE-2433', '2015-08-31 10:04:59', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '1', 'YD', null, null, '\r\n红外探头/蓝牙掌上电脑（不一定能买到）', '', '', '1.主要技术规格：\r\n（1）额定电压：3*415V\r\n（2）标定电流：3*5（6）A（在1A或5A之间可编程）\r\n（3）频率：50HZ\r\n2. 主要功能\r\n（1）计量总的正向有功电能和反向有功电能及每相的正向和反向有功电能。\r\n（2）多费率\r\n（3）负荷曲线---至少365天\r\n（4）计量最大需量\r\n（5）事件记录---防窃电等50个事件记录\r\n（6）防窃电----防CT短接，反接，逆相序，掉相线，掉零线，外部磁场干扰，高压警棍电击等\r\n（7）通讯接口---RS485接口，近红外探头通讯和掌上电脑抄读，此', '20个', '');
INSERT INTO `crs_tabledata687` VALUES ('2999', '{6241C22B-3BAE-463C-BA62-ECAA3A87A070}', '0', 'JXINHE-2433', '2015-11-12 10:59:36', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '1', 'YI', null, null, '单相两线可更换模块电表', '', '', '1.主要技术规格：(1）额定电流：10-80A;(2)额定电压：230±20%V;(3)频率：50HZ \r\n2.主要功能：（1）计量功能---分别计量输入有功电能计量，输出有功电能计量。 （2）多费率---至少4个费率 （3）负荷曲线---多通道，至少6个月（4）计量最大需量 （5）事件记录---记录至少12月的历史数据（6）防窃电----电表盖和端子盖开盖，反接，短接，负载部分接地和全部接地，静电放电，外部磁场干扰，高压警棍电击，断零线等 （7）通讯接口---RS485接口，近红外探头通讯接口 （8）停', '90000台', '');
INSERT INTO `crs_tabledata687` VALUES ('3000', '{6241C22B-3BAE-463C-BA62-ECAA3A87A071}', '0', 'JXINHE-2433', '2015-11-16 09:04:50', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '1', 'YJ', null, null, '三相四线可更换模块电表', '', '', '1.主要技术规格：(1）额定电流：10-100A;(2)额定电压：3*230V;(3)频率：50HZ\r\n2.主要功能：（1）计量功能---输入有功电能计量，输出有功电能计量。 （2）多费率---至少4个费率 （3）负荷曲线（4）计量最大需量 （5）事件记录---防窃电，开电表盖，开端子盖，磁场干扰，掉相，反向逆流等事件记录 （6）防窃电----反接，逆相序，掉相线，掉零线，外部磁场干扰，高压警棍电击等 （7）通讯接口---RS485接口，近红外探头通讯接口\r\n3.特殊要求（1）主要元器件（CPU，RAM，', '6000台', '');
