INSERT INTO `crs_tabledata687` VALUES ('3069', '{6241C22B-3BAE-463C-BA62-ECAA3A87A140}', '0', 'INHE-0088', '2014-08-27 17:14:12', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '1', 'DR', null, null, '单相2线普通圆表120V C100 1S-1008037', '19', '暂无', '具体请见附件。\r\n所有产品质保3年，\r\n普通圆表需停电显示、有功计量；\r\nPLC圆表需带TWACS模块（Aclara产品，要求我司电表适应其模块），此产品目前主要由ELSTER供货；\r\n三相GPRS圆表目前主要由Itron供货。\r\n\r\n招标要求至少提交一台样机，产品需要有当地INDOCAL认证，也需一台样机，认证时间10-14天，最长一个月，需要在截标前提交样机进行认证，如未在截标前完成也可延期提交证书。\r\n超过1万台需安排工厂验货。', '24104', '');
INSERT INTO `crs_tabledata687` VALUES ('3070', '{6241C22B-3BAE-463C-BA62-ECAA3A87A141}', '0', 'INHE-0088', '2014-08-27 17:14:12', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '1', 'DR', null, null, '\r\n单相3线普通圆表240V C200 2S-1008050', '23', '暂无', '具体请见附件。\r\n所有产品质保3年，\r\n普通圆表需停电显示、有功计量；\r\nPLC圆表需带TWACS模块（Aclara产品，要求我司电表适应其模块），此产品目前主要由ELSTER供货；\r\n三相GPRS圆表目前主要由Itron供货。\r\n\r\n招标要求至少提交一台样机，产品需要有当地INDOCAL认证，也需一台样机，认证时间10-14天，最长一个月，需要在截标前提交样机进行认证，如未在截标前完成也可延期提交证书。\r\n超过1万台需安排工厂验货。', '28714', '');
