INSERT INTO `crs_tabledata687` VALUES ('3112', '{6241C22B-3BAE-463C-BA62-ECAA3A87A183}', '0', 'INHE-0222', '2015-12-05 22:31:49', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '1', 'FIX', null, null, '100A单相2线可更换通讯模块智能电表RF通讯', '', '', '1.标书如附件，附件中技术规格需求为ANSI表，目前在运作IEC标准智能电表规格。\r\n2.电力公司及融资方要求智能后付费电表，未来可通过使用模块升级为AMI系统，且在上AMI系统之前，要解决入户抄表问题，故倾向使用RF通讯的模块表，可使用HHU抄表。\r\n\r\n2.重点难度为：\r\n2.1 单相3线可更换模块表为100A\r\n2.2 单相表MCU用HHU或未来使用集中器RF抄表，MCU和CIU之间要求PLC通讯。\r\n需要公司尽快评估方案。', '15094', '');
