INSERT INTO `crs_tabledata687` VALUES ('3173', '{6241C22B-3BAE-463C-BA62-ECAA3A87A244}', '0', 'JXINHE-1277', '2014-12-22 17:10:49', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '0', 'MU', null, null, '单相电子式智能电表', '', '', '备注：\r\n\r\n需要提供单、三相表样机各两台，以便代理提交给电力公司进行测试。我司产品的质量需要经过电力公司的测试。同时，提供我司实验室测试的相关重要测试报告，作为随附样机的文件同时交由电力部。关于低压50V，已和代理沟通，75V的电压会更合理一些，代理已经同意并向电力公司解释，我司提出的方案会更合理。', '', '');
