INSERT INTO `crs_tabledata687` VALUES ('3185', '{6241C22B-3BAE-463C-BA62-ECAA3A87A256}', '0', 'JXINHE-1345', '2015-01-06 09:03:28', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '0', 'ZG', null, null, 'BS安装单相可更换通信模块代码智能电表(无CIU）PLC通讯', '', '', '1.电表显示项需有：a. 有功电量（正向，反向，绝对值） b.无功电量（正向，反向，绝对值） c.最大有功需量（正向，反向）d.累计有功需量（正向，反向） f.最大无功需量（正向，反向） g.累计无功需量（正向，反向） h.瞬时有功功率 i.瞬时无功功率 j. 瞬时电压k.瞬时电流 l.瞬时功率因素或相位角\r\n\r\n2.电表在集中器，AMI中央系统,上位机系统中自动注册。\r\n\r\n3.电表需能够设置有功无功需量和持续时间。\r\n\r\n4.电压上升下降检测，并且检测的时间可以设置；长时间和短时间断电可以检测，并且检', '26355', '');
INSERT INTO `crs_tabledata687` VALUES ('3186', '{6241C22B-3BAE-463C-BA62-ECAA3A87A257}', '0', 'JXINHE-1345', '2015-01-06 09:03:28', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '0', 'ZG', null, null, '\r\nBS安装单相可更换通信模块代码智能电表(无CIU）PLC通讯', '', '', '1.电表显示项需有：a. 有功电量（正向，反向，绝对值） b.无功电量（正向，反向，绝对值） c.最大有功需量（正向，反向）d.累计有功需量（正向，反向） f.最大无功需量（正向，反向） g.累计无功需量（正向，反向） h.瞬时有功功率 i.瞬时无功功率 j. 瞬时电压k.瞬时电流 l.瞬时功率因素或相位角\r\n\r\n2.电表在集中器，AMI中央系统,上位机系统中自动注册。\r\n\r\n3.电表需能够设置有功无功需量和持续时间。\r\n\r\n4.电压上升下降检测，并且检测的时间可以设置；长时间和短时间断电可以检测，并且检', '5000', '');
