INSERT INTO `crs_tabledata687` VALUES ('3189', '{6241C22B-3BAE-463C-BA62-ECAA3A87A260}', '0', 'JXINHE-1345', '2015-04-29 09:15:58', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '0', 'ZM', null, null, ' ', ' ', ' ', '\r\n\r\n技术规格翻译件，请见附件。\r\n客户希望安排我们的工程师和PEA的工程师会面，更加深入理解技术规格，确保我们的产品完全满足PEA的要求。', ' ', '');
INSERT INTO `crs_tabledata687` VALUES ('3190', '{6241C22B-3BAE-463C-BA62-ECAA3A87A261}', '0', 'INHE-0403', '2015-08-15 18:28:26', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '0', '海龟', null, null, '三相四线DTZ1513', '', '', '之前我们没能满足的两点依旧是技术规格的关键。（1） ANSI optical port （2）DB9, female  见附件样机图片以及技术规格。', '12000', '');
INSERT INTO `crs_tabledata687` VALUES ('3191', '{6241C22B-3BAE-463C-BA62-ECAA3A87A262}', '0', 'INHE-0403', '2015-05-21 09:54:21', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '0', 'T12', null, null, '单项简单表', '', '', '见附件\r\n\r\n需求：用户需要卡表，按照项目，在每个月的开始要有固定的130kWh的用电额度（免费）转入客户的卡内。这一额度可以通过软件改变加密。用户使用的电量如果在此范围内无需充值。如果用户消费超过固定额度（例如：130kWh），用户可以到经销公司，为电卡充值。如果用户没有将本月的用电额度使用完，可以累积到下个月，130kWh的用电额度可以再每个月初自动转到用户的卡（电表）里。\r\n目前询问样机价格', '', '');
