INSERT INTO `crs_tabledata687` VALUES ('3198', '{6241C22B-3BAE-463C-BA62-ECAA3A87A269}', '0', 'INHE-0329', '2015-03-13 10:00:13', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '0', 'MCC', null, null, 'BS安装单相PLC可更换模块代码智能电表', '', '', '经过介绍我司产品，客户指定要DDZ1513T(PLC)以及DDZ1513T(PLC)，要求电表能够通过PLC/GPRS远程通信，未来能够实现AMR，供应商能提供管理系统。\r\n根据客户要求以及当地市场登记的其它厂商的表型（见附件），推荐我司以上产品：BS安装单相PLC可更换模块代码智能电表，BS安装三相PLC可更换模块代码智能电表。样机基本参数设置见附件。', '', '');
