INSERT INTO `crs_tabledata687` VALUES ('3274', '{6241C22B-3BAE-463C-BA62-ECAA3A87A345}', '0', 'INHE-0228', '2015-01-08 09:59:18', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '0', 'NGN', null, null, 'BS安装单相可更换通信模块代码智能电表（不带通信模块）', '', '', '1.关于表计\r\n技术规格中，没有要求电表的通讯方式，但是在软件的需求中，又要求能集抄电表。因此建议使用模块表，且不带通讯模块。以后如果客户又需求，可以自行扩展。\r\n\r\n2.关于软件\r\n有部分软件的功能目前不存在，如接线合同信息的录入，等。如果中标，将需要给电力公司做系统的展示，届时需要对软件进行相应的更改。\r\n\r\n其他技术规格，详见附件。', '6000', '');
INSERT INTO `crs_tabledata687` VALUES ('3275', '{6241C22B-3BAE-463C-BA62-ECAA3A87A346}', '0', 'INHE-0228', '2015-01-08 09:59:18', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '0', 'NGN', null, null, '\r\n三相四线直接接入式可更换通信模块代码智能电表（不带通信模块）', '', '', '1.关于表计\r\n技术规格中，没有要求电表的通讯方式，但是在软件的需求中，又要求能集抄电表。因此建议使用模块表，且不带通讯模块。以后如果客户又需求，可以自行扩展。\r\n\r\n2.关于软件\r\n有部分软件的功能目前不存在，如接线合同信息的录入，等。如果中标，将需要给电力公司做系统的展示，届时需要对软件进行相应的更改。\r\n\r\n其他技术规格，详见附件。', '2000', '');
INSERT INTO `crs_tabledata687` VALUES ('3276', '{6241C22B-3BAE-463C-BA62-ECAA3A87A347}', '0', 'INHE-0228', '2015-01-08 09:59:18', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '0', 'NGN', null, null, '\r\n售电系统（4个系统）', '', '', '1.关于表计\r\n技术规格中，没有要求电表的通讯方式，但是在软件的需求中，又要求能集抄电表。因此建议使用模块表，且不带通讯模块。以后如果客户又需求，可以自行扩展。\r\n\r\n2.关于软件\r\n有部分软件的功能目前不存在，如接线合同信息的录入，等。如果中标，将需要给电力公司做系统的展示，届时需要对软件进行相应的更改。\r\n\r\n其他技术规格，详见附件。', '1', '');
INSERT INTO `crs_tabledata687` VALUES ('3277', '{6241C22B-3BAE-463C-BA62-ECAA3A87A348}', '0', 'INHE-0415', '2015-06-25 17:32:04', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '0', 'ZES03', null, null, 'DIN安装单相分体式预付费电表', '', '', '1.LOT1和 LOT2技术规格一致:DIN安装单相两线分体式预付费电表\r\n2.LOT3:DIN安装单相两线分体式预付费电表，CIU需满足：common base安装\r\n3 安装环境：电线杆  \r\n4.MCU 和CIU之间通讯方式：PLC\r\n5.所有的表需带单独的表箱以及所有必要的配件\r\n6.具体技术规格请参见附件\r\n\r\n', '25000', '');
