INSERT INTO `crs_tabledata687` VALUES ('3329', '{6241C22B-3BAE-463C-BA62-ECAA3A87A400}', '0', 'INHE-0051', '2015-07-30 17:09:20', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '0', 'ESM', null, null, '（DIN还是BS安装，不确定）单相分体式（G3 PLC或RF）代码智能电表', '', '', '见附件。技术规格内容很多，是ESKOM的标准技术规格，建议客服和研发详细阅读。\r\n\r\n1.电表和CIU通过G3 PLC或RF通讯，电表和集中器通过符合DLMS和IDIS 的G3 PLC或RF通讯，集中器和管理中心通过3G/LTE/光纤通讯。后期可能会增加负荷控制设备。\r\n2.厂家必须执行软件指控流程以开发和维护预付费电表，类似于ISO12207的要求\r\n3.产品必须通过IDIS认证，并且有IDIS标识。\r\n4.单相要求安装在DIN导轨上，可以是上进下出的接线，最好端子在底部。\r\n5.三相表最大电流至少每相', '17100', '');
INSERT INTO `crs_tabledata687` VALUES ('3330', '{6241C22B-3BAE-463C-BA62-ECAA3A87A401}', '0', 'INHE-0051', '2015-07-30 17:09:20', '0000-00-00 00:00:00', null, 'unchecked', 'n', 'n', null, '0', 'ESM', null, null, '\r\n三相四线直接接入分体式（G3 PLC或RF）代码智能电表', '', '', '见附件。技术规格内容很多，是ESKOM的标准技术规格，建议客服和研发详细阅读。\r\n\r\n1.电表和CIU通过G3 PLC或RF通讯，电表和集中器通过符合DLMS和IDIS 的G3 PLC或RF通讯，集中器和管理中心通过3G/LTE/光纤通讯。后期可能会增加负荷控制设备。\r\n2.厂家必须执行软件指控流程以开发和维护预付费电表，类似于ISO12207的要求\r\n3.产品必须通过IDIS认证，并且有IDIS标识。\r\n4.单相要求安装在DIN导轨上，可以是上进下出的接线，最好端子在底部。\r\n5.三相表最大电流至少每相', '15785', '');
